Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

using ll = long long;

const int MAX_N = 10;
const int MAX_M = 25;
const int MAX_S = 1048580;
const int MOD = 1000000007;

int n;
int prob[MAX_N][MAX_N];
int match_flag[MAX_N][MAX_N];
int two_pow[MAX_M];
int arr_a[MAX_N], arr_b[MAX_N];
int f_arr[MAX_S], g_arr[MAX_S];
int state_count;
int state_map[70];
int point_set[MAX_M][MAX_N];
int state_stack[MAX_M];
bool visited_flag[MAX_N];

int power_mod(int base, int exponent) {
    int result = 1;
    while (exponent) {
        if (exponent & 1) result = (ll)result * base % MOD;
        base = (ll)base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

void setup() {
    two_pow[0] = 1;
    for (int i = 1; i <= 20; ++i) two_pow[i] = two_pow[i-1] << 1;
    scanf("%d", &n);
    int inv_100 = power_mod(100, MOD - 2);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            scanf("%d", &prob[i][j]);
            prob[i][j] = (ll)prob[i][j] * inv_100 % MOD;
        }
    while (n < 6) {
        prob[++n][n] = 1;
    }
}

bool find_matching(int pos) {
    if (pos > 3) return true;
    for (int candidate = 1; candidate <= 3; ++candidate) {
        if (!visited_flag[candidate] && match_flag[arr_a[pos]][arr_b[candidate]]) {
            visited_flag[candidate] = true;
            if (find_matching(pos + 1)) {
                visited_flag[candidate] = false;
                return true;
            }
            visited_flag[candidate] = false;
        }
    }
    return false;
}

void explore_second(int row, int col, int current_weight) {
    if (row > 3) {
        int mask = 0;
        for (int idx = 1; idx <= state_count; ++idx) {
            for (int k = 1; k <= 3; ++k) arr_b[k] = point_set[idx][k];
            if (find_matching(1)) mask |= two_pow[idx - 1];
        }
        f_arr[mask] = (f_arr[mask] + current_weight) % MOD;
        return;
    }
    match_flag[arr_a[row]][col] = 0;
    if (col == n) explore_second(row + 1, 1, (ll)current_weight * (1 - prob[arr_a[row]][col] + MOD) % MOD);
    else explore_second(row, col + 1, (ll)current_weight * (1 - prob[arr_a[row]][col] + MOD) % MOD);
    match_flag[arr_a[row]][col] = 1;
    if (col == n) explore_second(row + 1, 1, (ll)current_weight * prob[arr_a[row]][col] % MOD);
    else explore_second(row, col + 1, (ll)current_weight * prob[arr_a[row]][col] % MOD);
}

void explore_first(int index, int count, int bitmask) {
    if (count == 3) {
        state_map[bitmask] = ++state_count;
        state_stack[state_count] = bitmask;
        for (int i = 1; i <= 3; ++i) point_set[state_count][i] = arr_a[i];
        return;
    }
    if (index > n) return;
    explore_first(index + 1, count, bitmask);
    arr_a[count + 1] = index;
    explore_first(index + 1, count + 1, bitmask | two_pow[index - 1]);
}

void preprocess_g() {
    for (int i = 0; i < state_count; ++i)
        for (int j = 0; j < (1 << state_count); ++j)
            if (j & two_pow[i]) g_arr[j] = (g_arr[j] + g_arr[j ^ two_pow[i]]) % MOD;
}

int main() {
    setup();
    explore_first(1, 0, 0);
    arr_a[1] = 1; arr_a[2] = 2; arr_a[3] = 3;
    explore_second(1, 1, 1);
    for (int i = 0; i < (1 << state_count); ++i) {
        int new_mask = 0;
        for (int j = 1; j <= state_count; ++j) {
            int complement_id = state_map[(1 << n) - 1 - state_stack[j]];
            if (i & two_pow[j - 1]) new_mask |= two_pow[complement_id - 1];
        }
        g_arr[new_mask] = f_arr[i];
        f_arr[i] = 0;
    }
    arr_a[1] = 4; arr_a[2] = 5; arr_a[3] = 6;
    explore_second(1, 1, 1);
    preprocess_g();
    int result = 0;
    for (int i = 0; i < (1 << state_count); ++i)
        result = (result + (ll)f_arr[i] * g_arr[(1 << state_count) - 1 - i] % MOD) % MOD;
    printf("%d\n", (MOD + 1 - result) % MOD);
    return 0;
}
